CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version>0),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS repositories(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),version INTEGER NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY,version INTEGER NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS participant_projects(participant_id TEXT REFERENCES participants(id),project_id TEXT REFERENCES projects(id),PRIMARY KEY(participant_id,project_id));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES participants(id),version INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('active','ended')),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS tokens(hash TEXT PRIMARY KEY,actor_id TEXT NOT NULL,kind TEXT NOT NULL,session_id TEXT REFERENCES sessions(id),project_id TEXT REFERENCES projects(id),revoked INTEGER NOT NULL DEFAULT 0,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),version INTEGER NOT NULL,spec_version INTEGER NOT NULL DEFAULT 1,phase TEXT NOT NULL,collaborator_limit INTEGER NOT NULL CHECK(collaborator_limit>=0),integrator_id TEXT REFERENCES participants(id),integrator_session_id TEXT REFERENCES sessions(id),integrator_epoch INTEGER NOT NULL DEFAULT 0,body TEXT NOT NULL CHECK(json_valid(body)),CHECK(phase NOT IN('active','integrating','review') OR (integrator_id IS NOT NULL AND integrator_session_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),version INTEGER NOT NULL,claim_participant_id TEXT REFERENCES participants(id),claim_session_id TEXT REFERENCES sessions(id),claim_epoch INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),CHECK((claim_participant_id IS NULL)=(claim_session_id IS NULL)));
CREATE TABLE IF NOT EXISTS memberships(task_id TEXT REFERENCES tasks(id),participant_id TEXT REFERENCES participants(id),role TEXT NOT NULL CHECK(role IN('integrator','worker')),PRIMARY KEY(task_id,participant_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_integrator ON memberships(task_id) WHERE role='integrator';
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT REFERENCES tasks(id),thread_id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS message_receipts(message_id TEXT REFERENCES messages(id),participant_id TEXT REFERENCES participants(id),state TEXT NOT NULL,version INTEGER NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(message_id,participant_id));
CREATE TABLE IF NOT EXISTS decision_requests(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT NOT NULL REFERENCES tasks(id),version INTEGER NOT NULL,scope_key TEXT NOT NULL,state TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_question ON decision_requests(task_id,scope_key) WHERE state='pending';
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES decision_requests(id),version INTEGER NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),UNIQUE(request_id,version));
CREATE TABLE IF NOT EXISTS deliveries(id TEXT PRIMARY KEY,assignment_id TEXT NOT NULL REFERENCES assignments(id),revision INTEGER NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),UNIQUE(assignment_id,revision));
CREATE TABLE IF NOT EXISTS integrations(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS acceptances(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),candidate_id TEXT NOT NULL REFERENCES integrations(id),actor_id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE UNIQUE INDEX IF NOT EXISTS one_candidate_acceptance ON acceptances(candidate_id,actor_id);
CREATE TABLE IF NOT EXISTS acceptance_candidates(id TEXT PRIMARY KEY REFERENCES integrations(id),task_id TEXT NOT NULL REFERENCES tasks(id),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS delivery_reviews(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES deliveries(id),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS completions(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS offline_candidates(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),actor_id TEXT NOT NULL,local_id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),UNIQUE(actor_id,local_id));
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT,scope TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),received_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_scope_seq ON events(scope,seq);
CREATE TABLE IF NOT EXISTS request_receipts(actor_id TEXT NOT NULL,scope TEXT NOT NULL,request_key TEXT NOT NULL,content_hash TEXT NOT NULL,event_id INTEGER NOT NULL REFERENCES events(seq),result TEXT NOT NULL CHECK(json_valid(result)),PRIMARY KEY(actor_id,scope,request_key));
CREATE TABLE IF NOT EXISTS bindings(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),version INTEGER NOT NULL,kind TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS external_jobs(id TEXT PRIMARY KEY,binding_id TEXT NOT NULL REFERENCES bindings(id),task_id TEXT NOT NULL REFERENCES tasks(id),version INTEGER NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,dedupe_key TEXT NOT NULL UNIQUE,retry_at TEXT,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS external_receipts(job_id TEXT PRIMARY KEY REFERENCES external_jobs(id),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE IF NOT EXISTS outbound_channels(channel_key TEXT PRIMARY KEY,next_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS handoffs(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),version INTEGER NOT NULL,state TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_handoff ON handoffs(task_id) WHERE state='pending';
PRAGMA application_id=0x524F4F4D;
PRAGMA user_version=1;
